// 热搜热度计算核心代码
public double calculateHotScore(long baseScore, long timestamp, double userWeight) {
    long now = System.currentTimeMillis();
    double hours = (now - timestamp) / 3600000.0;
    double lambda = 0.1;
    double timeDecay = Math.exp(-lambda * hours);
    return baseScore * timeDecay * userWeight;
}

// Feed 流核心代码
public List<Feed> getFeed(String userId, String cursor, int limit) {
    List<String> followees = followService.getFollowees(userId);
    List<Feed> feeds = new ArrayList<>();
    for (String followee : followees) {
        feeds.addAll(feedDao.getLatestByUser(followee, cursor, limit));
    }
    List<Feed> inbox = feedDao.getInbox(userId, cursor, limit);
    feeds.addAll(inbox);
    feeds.sort((a, b) -> {
        int timeCompare = Long.compare(b.getTimestamp(), a.getTimestamp());
        if (timeCompare != 0) return timeCompare;
        return Double.compare(b.getHotScore(), a.getHotScore());
    });
    return feeds.subList(0, Math.min(limit, feeds.size()));
}

// 站内信核心代码
public void sendNotification(String userId, String type, String content) {
    if ("system".equals(type)) {
        notificationDao.insertSystemNotification(content);
    } else {
        String inboxKey = "inbox:" + userId;
        redis.lpush(inboxKey, content);
        redis.expire(inboxKey, 7 * 24 * 3600);
        if (webSocketService.isOnline(userId)) {
            webSocketService.push(userId, content);
        } else {
            pushService.push(userId, content);
        }
    }
}

// 附近的人核心代码（Redis GEO）
public List<User> findNearby(double longitude, double latitude, double radiusKm) {
    GeoRadiusCommandArgs args = GeoRadiusCommandArgs.newGeoRadiusArgs().includeCoordinates().includeDistance().sortAscending().count(100);
    GeoResults<GeoCoordinate> results = redis.georadius("users:geo", longitude, latitude, radiusKm, GeoUnit.KILOMETERS, args);
    List<User> users = new ArrayList<>();
    for (GeoResult<GeoCoordinate> result : results) {
        double distance = haversine(longitude, latitude, result.getContent().getX(), result.getContent().getY());
        if (distance <= radiusKm) users.add(new User(result.getContent().getName(), distance));
    }
    return users;
}

// 搜索推荐核心代码
public List<Item> search(String query, String userId) {
    List<Item> recall1 = esSearch(query);
    List<Item> recall2 = vectorSearch(query, userId);
    List<Item> recall3 = hotSearch();
    List<Item> merged = merge(recall1, recall2, recall3);
    List<Item> ranked = rank(merged, userId);
    return rerank(ranked);
}

// CDN 缓存策略核心代码
public String getResource(String url) {
    String cached = redis.get("cdn:" + url);
    if (cached != null) return cached;
    String content = fetchFromOrigin(url);
    redis.setex("cdn:" + url, 3600, content);
    return content;
}
